export interface SetValue {
  name?: string;
  /** May contain `{{variable}}`. */
  value?: string;
  where?: SetWhere;
}

export type SetWhere =
  | "header"
  | "cookie"
  /** A query, form or top-level JSON parameter that's already in the request. */
  | "param";

export type Severity = "info" | "low" | "medium" | "high";

export type Signature =
  | {
      state: "unsigned";
    }
  /** A valid signature; `trusted` when its key is on the user's list. */
  | {
      key: string;
      signer: string;
      state: "signed";
      trusted: boolean;
    };

/** Query of `GET /sitemap`. */
export interface SiteQuery {
  /** Only this host (empty: all). */
  host?: string | null;
}

export interface SiteView {
  in_scope: boolean;
  origin: string;
  root: Node;
  total: number;
}

export interface Skill {
  /** Arguments the text takes (`{{name}}`); all optional. */
  args: string[];
  description: string;
  name: string;
  /** "builtin" or "user". */
  source: string;
  title: string;
}

export interface Skipped {
  reason: string;
  url: string;
}

export interface Skipped2 {
  finding_id: number;
  reason: string;
  title: string;
}

/** Body of `POST /collaborator/smtp`. */
export interface SmtpBody {
  /** Address to listen on, `host:port`. */
  listen: string;
}

/** Body of `POST /model/snapshots`. */
export interface SnapshotBody {
  /** Name for the snapshot. */
  name: string;
}

export interface SnapshotInfo {
  actor: string;
  created_ms: number;
  id: number;
  name: string;
  operations: number;
}

/** A short, single-line excerpt around `range`, plus where the match sits in it. */
export interface Snippet {
  end: number;
  /** Character offsets of the match within `text`. */
  start: number;
  text: string;
}

/** What the sandbox can do on this machine. */
export interface Status {
  /** CPU, memory, file size and open-file limits apply. */
  limits: boolean;
  /** Plugins can't reach the network. */
  network_isolated: boolean;
  /** One line for people. */
  summary: string;
}

/** `?status=`: filter a list by status (`all` or empty means no filter where the route says so). */
export interface StatusQuery {
  /** Only rows with this status. */
  status?: string | null;
}

export interface TargetAnalysis {
  content_types: { [key: string]: number };
  /** URLs that take input (with a query or a body), up to 300. */
  dynamic_urls: string[];
  host_filter: string | null;
  methods: { [key: string]: number };
  params: ParamSummary[];
  requests: number;
  static_urls: number;
  statuses: { [key: string]: number };
  /** Distinct URLs (path with query) and how many are static files. */
  urls: number;
}

export interface TestFinding {
  id: number;
  severity: string;
  title: string;
  url: string;
  vuln_class: string;
}

export interface TokenAnalyzerRequest {
  /** Run a previously approved request. All other fields must be identical. */
  approval_id?: string | null;
  /** The request that issues a token (e.g. a login or a page setting a cookie). */
  exchange_id: number;
  /** Send with this test identity's credentials (names from the identities list; "anonymous" for none). */
  identity?: string | null;
  /** Where the token is: cookie:<name>, header:<name>, json:/pointer or between:<start>|<end>. */
  locator: string;
  /** How many tokens to collect (default 100, 10–500). */
  samples?: number | null;
}

export type TokenAnalyzerResult =
  /** Statistics only: the tokens themselves are live secrets and aren't returned. */
  | {
      analysis: Analysis;
      exchange_ids: number[];
      found: number;
      requests: number;
      status: "done";
    }
  | {
      approval_id: string;
      reasons: string[];
      status: "pending_approval";
      summary: string;
    }
  | {
      reasons: string[];
      status: "denied";
    };

/** Body of `POST /tools/token-analyzer/analyze`. */
export interface TokensBody {
  /** Tokens to analyze (session ids, CSRF tokens, ...). */
  tokens: string[];
}

export type ToolProfile = "full" | "compact";

/** Body of `POST /traffic/triage`. */
export interface TriageBody {
  /** Only exchanges whose host contains this. */
  host?: string | null;
  /** Only exchanges in (true) or out of (false) scope. */
  in_scope?: boolean | null;
  /** Most rows to return (default 100). */
  limit?: number | null;
}

/** A recorded request worth testing (see `traffic_triage`). */
export interface TriageItem {
  exchange_id: number;
  hints: Hint[];
  method: string;
  /** Sum of the hints' weights. */
  score: number;
  /** Other recorded requests with the same method and path shape. */
  similar: number;
  url: string;
}

/** What one user message produced. */
export interface Turn {
  chat_id: number;
  /** Messages added in this turn (user, assistant and tool results). */
  messages: Message[];
  /** Set when the turn ended early (step limit). */
  note?: string | null;
}

/** Body of `POST /update/check`. */
export interface UpdateCheck {
  /** Ask now even if the daily check is off or the last answer is fresh. */
  force?: boolean;
}

/** Body of `PUT /update`. */
export interface UpdateSet {
  /** Check for new versions once a day. */
  enabled: boolean;
}

export interface UpdateStatus {
  /** The newest release is newer than this build. */
  available: boolean;
  /** Unix seconds of the last check that got an answer. */
  checked_at?: number | null;
  current: string;
  /** Check once a day when the UI is open. */
  enabled: boolean;
  /** The newest release seen then (e.g. "v0.2.0") and its page. */
  latest?: string | null;
  url?: string | null;
}

export interface UpstreamProxy {
  /** Hosts reached directly: `example.com`, `*.example.com` or `*`. */
  bypass?: string[];
  host?: string;
  kind?: ProxyKind;
  password?: string;
  port?: number;
  /**
   * Let the proxy resolve target names: "socks5h" for SOCKS5; for HTTP
   * proxies, CONNECT tunnels name the host instead of the checked address
   * (for proxies that only allow named hosts). Off by default so the proxy
   * connects to the address ProxyMind resolved and checked against the
   * denied networks. Plain HTTP through an HTTP proxy always goes by name.
   */
  remote_dns?: boolean;
  /** Optional login (Basic for HTTP proxies, username/password for SOCKS5). */
  username?: string;
}

/**
 * When a response means the session is gone. Empty: 401, 419, 440 or a
 * redirect to a login page.
 */
export interface Validity {
  /** Text in the response (head or body) that means logged out. */
  contains?: string;
  statuses?: number[];
}

export type View =
  /** Request line, status, key headers, short body preview. */
  | "summary"
  /** All headers, no bodies. */
  | "headers"
  /** Everything, truncated to the token budget. */
  | "full";

/**
 * What the response looks like while the finding is still there (all set
 * conditions must hold).
 */
export interface VulnerableIf {
  /**
   * At least one of these appears in the body (e.g. the owner's email in
   * another user's response).
   */
  body_contains_any?: string[];
  /** The payload comes back unencoded. */
  reflects_payload?: boolean;
  /** The request is slower than the baseline by at least this many ms (median). */
  slower_by_ms?: number | null;
  status_max?: number | null;
  status_min?: number | null;
}

export interface WaybackCapture {
  /** Traffic has shown this path already. */
  known: boolean;
  mime?: string;
  /** Why it deserves a look (backup, config, API, admin…), if it does. */
  note?: string | null;
  status?: number | null;
  /** YYYYMMDDhhmmss */
  timestamp: string;
  url: string;
}

export interface WaybackReport {
  captures: WaybackCapture[];
  host: string;
  interesting: number;
  /** Captures on this host (before `limit` cut the list). */
  total: number;
}

/** A message in the history across connections. */
export interface WsHistoryItem {
  /** permessage-deflate data that couldn't be inflated, shown as is. */
  compressed: boolean;
  exchange_id: number;
  /** "client" (browser → server) or "server". */
  from: string;
  hex?: string | null;
  host: string;
  id: number;
  /** text, binary, close, ping, pong. */
  kind: string;
  /** Full payload length on the wire (decompressed when inflated). */
  len: number;
  path: string;
  possible_prompt_injection?: string[];
  /** Text payloads (and close reasons); binary ones get `hex` instead. */
  text?: string | null;
  /** Only part of the payload is shown. */
  truncated: boolean;
  ts_ms: number;
}

export interface WsHistoryPage {
  messages: WsHistoryItem[];
  /** Pass as `before_id` for older messages. */
  next_before_id?: number | null;
}

/** Query of `GET /ws/history`. */
export interface WsHistoryQuery {
  /** Only messages before this message id (for paging back). */
  before_id?: number | null;
  /** Only connections to this host (empty: all). */
  host?: string | null;
  /** Most messages to return (default 500). */
  limit?: number | null;
}

export interface WsMessageView {
  /** permessage-deflate data that couldn't be inflated, shown as is. */
  compressed: boolean;
  /** "client" (browser → server) or "server". */
  from: string;
  hex?: string | null;
  id: number;
  /** text, binary, close, ping, pong. */
  kind: string;
  /** Full payload length on the wire (decompressed when inflated). */
  len: number;
  possible_prompt_injection?: string[];
  /** Text payloads (and close reasons); binary ones get `hex` instead. */
  text?: string | null;
  /** Only part of the payload is shown. */
  truncated: boolean;
  ts_ms: number;
}

/** One message to send: `text`, or `hex` for binary data. */
export interface WsOut {
  /** Binary payload as hex (spaces allowed). */
  hex?: string | null;
  /** May contain `{{secret:...}}` placeholders. */
  text?: string | null;
}

export interface WsPage {
  exchange_id: number;
  messages: WsMessageView[];
  /** Pass as `after_id` to read the next page. */
  next_after_id?: number | null;
  notice?: string | null;
  total: number;
}

/** Query of `GET /exchanges/{id}/ws`. */
export interface WsQuery {
  /** Only messages after this message id. */
  after_id?: number | null;
  /** Most messages to return (default 200). */
  limit?: number | null;
}

export interface WsReplayRequest {
  /** From a previous pending_approval result: runs the approved send. All other fields must be identical. */
  approval_id?: string | null;
  /** A recorded WebSocket upgrade exchange (status 101). */
  exchange_id: number;
  /** Hypothesis this session tests (links the exchange as evidence). */
  hypothesis_id?: number | null;
  /** Open the socket as this test identity. */
  identity?: string | null;
  /** Characters of each message shown back (default 2000). */
  max_chars?: number | null;
  /** Sent in order, each followed by `wait_ms` of listening (at most 50). */
  messages?: WsOut[];
  /**
   * Edited upgrade request (HTTP/1.1). Default: the recorded one.
   * ProxyMind sets a fresh Sec-WebSocket-Key and turns compression off.
   */
  raw?: string | null;
  /**
   * How long to listen after each message (and after opening). Default
   * 1000, at most 10000; a whole session ends after 60 s.
   */
  wait_ms?: number | null;
}

export type WsReplayResult =
  /**
   * The socket opened; everything sent and received is recorded under
   * `exchange_id`.
   */
  | {
      /** "server" if the server closed the socket, else "proxymind". */
      closed_by: string;
      exchange_id: number;
      messages: WsPage;
      note?: string | null;
      status: "done";
    }
  /** The server didn't switch protocols (or couldn't be reached). */
  | {
      error?: string | null;
      exchange_id: number;
      http_status?: number | null;
      status: "not_upgraded";
    }
  | {
      approval_id: string;
      reasons: string[];
      status: "pending_approval";
      summary: string;
    }
  | {
      reasons: string[];
      status: "denied";
    };

export interface WsSearchHit {
  exchange_id: number;
  from_client: boolean;
  host: string;
  id: number;
  len: number;
  matches: number;
  path: string;
  snippets: Snippet[];
  ts_ms: number;
}

/** A search through WebSocket messages. */
export interface WsSearchRequest {
  /** Only messages with an id below this (for paging back). */
  before_id?: number | null;
  /** Match letter case. */
  case_sensitive?: boolean;
  /** client (to the server), server, or both (default). */
  direction?: "both" | "client" | "server";
  /** Host contains this text. */
  host?: string | null;
  /** Only connections whose targets are in scope. */
  in_scope?: boolean | null;
  /** Messages that don't match. */
  invert?: boolean;
  /** Most hits (default 50, max 500). */
  limit?: number | null;
  /** Messages to look at, newest first (default 5000, max 50 000). */
  max_scan?: number | null;
  /** Text (or a regex with `regex: true`) to find in message payloads. */
  query: string;
  /** Treat `query` as a regular expression. */
  regex?: boolean;
}

export interface WsSearchResult {
  hits: WsSearchHit[];
  next_before_id?: number | null;
  scanned: number;
}
